parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "summary": {
      "type": "string",
      "description": "A concise explanation of the debate outcome and reasoning behind the scores."
    },
    "supporting_score": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "Percentage score representing the strength and persuasiveness of the supporting agent's arguments."
    },
    "opposing_score": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "Percentage score representing the strength and persuasiveness of the opposing agent's arguments."
    },
    "confidence": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "Confidence level in the evaluation, based on argument quality and available information."
    }
  },
  "required": [
    "summary",
    "supporting_score",
    "opposing_score",
    "confidence"
  ],
  "additionalProperties": false
}
